s=s.replace("import { Claim, cents, daysOverdue, isCorrection, isOpen, money } from '../claims/claims';",
"import { Claim, cents, daysOverdue, dueBy, isCorrection, isOpen, money, plusDays } from '../claims/claims';")
old='''  const periods = Math.floor(daysOverdue(c, late.today) / 30);
  if (periods <= 0) return figure;
  return figure + (dueCents(figure * periods, valueOn(late.latePcts, c.date, START_LATE_PCT), halfUp) ?? 0);'''
new='''  const periods = Math.floor(daysOverdue(c, late.today) / 30);
  let charge = 0;
  for (let k = 1; k <= periods; k++) {
    const boundary = plusDays(dueBy(c), 30 * k);
    charge += dueCents(figure, valueOn(late.latePcts, boundary, START_LATE_PCT), halfUp) ?? 0;
  }
  return figure + charge;'''
assert old in s
s=s.replace(old,new)
old=''' * in force on the claim's date) with, when it is overdue, the late percent in force on the claim's
 * date of that figure for every full 30 days overdue added on top, rounded
 * to whole cents.'''
new=''' * in force on the claim's date) with, when it is overdue, a late charge added on top: for each full
 * 30 days overdue, the late percent in force on that boundary date (its due-by plus 30, 60, 90 ...
 * days) of that figure, rounded to whole cents, the charges added up.'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
